<?php
namespace App\Services\Payments;use App\Models\Payments\OrganizerPaymentProfile;
class SettlementRoutingService{public function resolve(?OrganizerPaymentProfile $profile):array{return $this->decide($profile);}
public function decide(?OrganizerPaymentProfile $profile,string $channel='web'):array{if(!$profile)return ['mode'=>'booktkit_managed','reason'=>'no_organizer_payment_profile'];$preferred=$profile->preferred_settlement_mode??$profile->settlement_mode??'booktkit_managed';if($preferred!=='razorpay_split')return ['mode'=>'booktkit_managed','reason'=>'organizer_prefers_booktkit_managed'];if($profile->split_suspended)return ['mode'=>'booktkit_managed','reason'=>'razorpay_split_suspended'];if(!$profile->split_enabled)return ['mode'=>'booktkit_managed','reason'=>'razorpay_split_not_enabled'];if(empty($profile->razorpay_account_id)||empty($profile->razorpay_product_id))return ['mode'=>'booktkit_managed','reason'=>'razorpay_account_not_ready'];if($profile->kyc_status!=='activated')return ['mode'=>'booktkit_managed','reason'=>'razorpay_kyc_'.($profile->kyc_status?:'pending')];if(!in_array($profile->razorpay_status,['active','activated'],true))return ['mode'=>'booktkit_managed','reason'=>'razorpay_'.($profile->razorpay_status?:'pending')];return ['mode'=>'razorpay_split','reason'=>'razorpay_route_eligible'];}}